<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount } from 'vue'
import { X, Save } from 'lucide-vue-next'
import { catalog, metadata, rules, categoryDefinitions, sources, vouchers, voucherStates, saveEntity, type Entity, type Values } from '../prototype-store'
import { people, observations, regions, statusLabels } from '../domain'
const props=defineProps<{entity:Entity;editId?:string}>(),emit=defineEmits<{close:[];saved:[message:string]}>()
const names:Record<Entity,string>={benefit:'Imtiyoz kartasi',rule:'Muvofiqlik qoidasi',category:'Kontingent',person:'Shaxs profili',usage:'Foydalanish / baholash yozuvi',voucher:'Elektron bog‘cha vaucheri',source:'Ma’lumot manbasi'}
interface Option{value:string;label:string}
interface Field{key:string;label:string;group:string;type?:string;required?:boolean;options?:Option[];hint?:string;min?:number;max?:number}
const opts=(rows:string[]):Option[]=>rows.map(value=>({value,label:value}))
const benefitOptions=computed(()=>catalog.map(b=>({value:String(b.id),label:`${b.id} · ${b.name}`})))
const categoryOptions=computed(()=>opts(categoryDefinitions.map(c=>c.name)))
const field=(key:string,label:string,group:string,type='text',required=true,options?:Option[],hint?:string):Field=>({key,label,group,type,required,options,hint})
const fields=computed<Field[]>(()=>{
 const general='Asosiy ma’lumotlar', conditions='Shartlar va amal qilish', binding='Bog‘lanishlar'
 switch(props.entity){
 case 'benefit':return [field('id','Imtiyoz raqami',general,'number'),field('name','Imtiyoz nomi',general),field('type','Chora turi',general,'select',true,opts([...new Set(['Imtiyoz','Moliyaviy ko‘mak','Ijtimoiy xizmat','Kafolat','Elektron vaucher',...catalog.map(b=>b.details.match(/Тури: ([^.\\n]+)/)?.[1]??'Boshqa')])])),field('description','Tavsif va oluvchilar uchun shartlar',general,'textarea'),field('legal','Huquqiy asos: hujjat, raqam, sana va band',conditions),field('start','Amal boshlanishi',conditions,'date'),field('end','Amal tugashi',conditions,'date'),field('categories','Oluvchilar kontingenti',binding,'multi',false,categoryOptions.value),field('organization','Mas’ul tashkilot',binding),field('source','Ma’lumot manbasi',binding,'select',false,[{value:'',label:'Manba aniqlanmagan'},...opts(sources.map(s=>s.name))])]
 case 'category':return [field('code','Kontingent kodi',general),field('name','Kontingent nomi',general),field('description','Toifaga kirish mezonlari va izoh',conditions,'textarea'),field('benefits','Tegishli imtiyozlar',binding,'multi',true,benefitOptions.value)]
 case 'person':return [field('name','F.I.Sh.',general),field('pinfl','JShShIR',general,'text',true,undefined,'14 raqam; boshidagi nollar saqlanadi.'),field('age','Yoshi',general,'number'),field('gender','Jinsi',general,'select',true,opts(['Ayol','Erkak'])),field('familyId','Oila identifikatori',general),field('region','Hudud','Yashash manzili','select',true,opts(regions)),field('district','Tuman / shahar','Yashash manzili'),field('mahalla','Mahalla','Yashash manzili'),field('registry','Ijtimoiy reyestr holati',conditions,'select',true,[{value:'true',label:'Reyestrda'},{value:'false',label:'Reyestrda emas'}]),field('categories','Kontingentlar',binding,'multi',true,categoryOptions.value)]
 case 'rule':return [field('benefitId','Imtiyoz',general,'select',true,benefitOptions.value),field('version','Qoida versiyasi',general),field('state','Qoida holati',general,'select',true,opts(['Loyiha','Faol'])),field('minAge','Eng kichik yosh',conditions,'number'),field('maxAge','Eng katta yosh',conditions,'number'),field('gender','Jins sharti',conditions,'select',false,[{value:'',label:'Cheklanmagan'},...opts(['Ayol','Erkak'])]),field('registry','Reyestr sharti',conditions,'select',false,[{value:'',label:'Talab qilinmaydi'},{value:'true',label:'Reyestrda bo‘lishi kerak'},{value:'false',label:'Reyestrga kiritilmagan'}]),field('categories','Mos kelishi kerak bo‘lgan kontingentlar',conditions,'multi',false,categoryOptions.value,'Bir nechta tanlansa, ulardan kamida bittasiga mansublik yetarli.'),field('start','Amal boshlanishi',conditions,'date'),field('end','Amal tugashi',conditions,'date')]
 case 'usage':return [field('personId','Shaxs',general,'select',true,people.map(p=>({value:p.id,label:`${p.name} · ${p.pinfl}`}))),field('benefitId','Imtiyoz',general,'select',true,benefitOptions.value),field('date','Voqea / baholash sanasi',general,'date'),field('status','Huquq va foydalanish holati',general,'select',true,Object.entries(statusLabels).map(([value,label])=>({value,label}))),field('source','Ma’lumot manbasi',binding,'select',true,opts(sources.map(s=>s.name))),field('sourceEventId','Manba hodisasi identifikatori',binding,'text',false,undefined,'Foydalanish tasdiqlangan holatlarda majburiy. Bir manbada takrorlanmaydi.'),field('amount','Tasdiqlangan summa, so‘m',binding,'number',false,undefined,'Summa noma’lum bo‘lsa, maydonni bo‘sh qoldiring. Nol va noma’lum qiymat farqlanadi.')]
 case 'voucher':return [field('id','Vaucher raqami',general),field('child','Bolaning F.I.Sh.',general),field('parent','Qonuniy vakil',general),field('region','Hudud',general,'select',true,opts(regions)),field('kindergarten','Bog‘cha nomi va raqami',binding),field('plan','Individual reja raqami',binding),field('start','Amal boshlanishi',conditions,'date'),field('end','Amal tugashi',conditions,'date'),field('state','Vaucher holati',conditions,'select',true,opts(voucherStates)),field('consent','Qonuniy vakil roziligi va vakilligi tasdiqlangan',conditions,'checkbox',true)]
 case 'source':return [field('name','Manba tizimi nomi',general),field('systemCode','Manba kodi',general),field('organization','Mas’ul tashkilot',general),field('description','Taqdim etadigan ma’lumotlari',general,'textarea',false),field('frequency','Yangilanish davriyligi','Yangilanish va sifat','select',true,opts(['Voqea bo‘yicha','Kunlik','Haftalik','Oylik'])),field('time','Oxirgi muvaffaqiyatli yangilanish','Yangilanish va sifat','datetime-local'),field('status','Manba holati','Yangilanish va sifat','select',true,opts(['Yangilangan','Kechikmoqda','Qisman ma’lumot'])),field('coverage','Ma’lumot to‘liqligi, %','Yangilanish va sifat','number')]
 }
})
function initial():Values{
 const v:Values={id:props.entity==='benefit'?String(Math.max(...catalog.map(b=>b.id))+1):`V-2026-${String(vouchers.length+1).padStart(4,'0')}`,start:'2026-10-01',end:'2027-09-30',type:'Imtiyoz',benefitId:String(catalog[0]!.id),personId:people[0]!.id,gender:'',registry:'',minAge:'0',maxAge:'120',version:'v1',state:props.entity==='rule'?'Loyiha':'Shakllangan',status:props.entity==='source'?'Yangilangan':'used',date:'2026-10-29',source:sources[0]!.name,region:regions[0]!,frequency:'Kunlik',time:'2026-10-29T09:00',coverage:'100',categories:[],benefits:[],consent:false}
 if(props.entity==='person'){v.gender='Ayol';v.registry='false'}
 if(!props.editId)return v
 let row:Record<string,unknown>|undefined
 if(props.entity==='benefit'){const b=catalog.find(b=>String(b.id)===props.editId)!;const m=metadata[b.id];row={...b,...m,type:m?.type??b.details.match(/Тури: ([^.\n]+)/)?.[1]??'Imtiyoz',legal:m?.legal??b.details.match(/Ҳуқуқий асос манба бўйича: (.*)/)?.[1]??'',description:m?.description??b.details};}
 if(props.entity==='category'){const c=categoryDefinitions.find(c=>c.name===props.editId);row=c?{...c,benefits:c.benefitIds.map(String)}:undefined}
 if(props.entity==='person')row=people.find(p=>p.id===props.editId) as unknown as Record<string,unknown>
 if(props.entity==='rule')row=rules.find(r=>`${r.benefitId}:${r.version}`===props.editId) as unknown as Record<string,unknown>
 if(props.entity==='usage')row=observations.find(r=>r.id===props.editId) as unknown as Record<string,unknown>
 if(props.entity==='voucher')row=vouchers.find(r=>r.id===props.editId) as unknown as Record<string,unknown>
 if(props.entity==='source')row=sources.find(r=>r.name===props.editId) as unknown as Record<string,unknown>
 if(row)for(const [k,value]of Object.entries(row))v[k]=Array.isArray(value)?[...value]:value===null?'':typeof value==='boolean'?(k==='consent'?value:String(value)):String(value)
 return v
}
const values=ref<Values>(initial()),error=ref(''),saving=ref(false),find=ref('')
const groups=computed(()=>[...new Set(fields.value.map(f=>f.group))])
const panel=ref<HTMLElement|null>(null),previousFocus=document.activeElement as HTMLElement|null
onMounted(()=>panel.value?.querySelector<HTMLElement>('input:not([readonly]),select,textarea,button')?.focus())
onBeforeUnmount(()=>previousFocus?.focus())
function trap(e:KeyboardEvent){if(e.key==='Escape'){emit('close');return}if(e.key!=='Tab')return;const elements=Array.from(panel.value?.querySelectorAll<HTMLElement>('input:not([disabled]),select:not([disabled]),textarea,button:not([disabled]),[tabindex="0"]')??[]);const first=elements[0],last=elements[elements.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
function submit(){error.value='';saving.value=true;try{saveEntity(props.entity,values.value,props.editId);emit('saved',`${names[props.entity]} ${props.editId?'tahrirlandi':'yaratildi'} va brauzerda saqlandi.`)}catch(e){error.value=e instanceof Error?e.message:'Saqlashda xato yuz berdi.'}finally{saving.value=false}}
function options(f:Field){return (f.options??[]).filter(o=>!find.value||o.label.toLowerCase().includes(find.value.toLowerCase()))}
</script>

<template>
<div class="editor-overlay" @click.self="emit('close')" @keydown="trap"><section class="editor" role="dialog" aria-modal="true" aria-labelledby="editor-title" ref="panel"><header><div><span>MA’LUMOTNI SHAKLLANTIRISH</span><h2 id="editor-title">{{ names[entity] }} · {{ editId?'tahrirlash':'yangi' }}</h2></div><button type="button" @click="emit('close')" aria-label="Shaklni yopish"><X :size="19" /></button></header><form @submit.prevent="submit"><div class="editor-body"><fieldset v-for="group in groups" :key="group"><legend>{{ group }}</legend><div class="editor-grid"><div class="editor-field" v-for="f in fields.filter(f=>f.group===group)" :key="f.key" :class="{wide:['textarea','multi','checkbox'].includes(f.type??'')}"><span>{{ f.label }} <b v-if="f.required">*</b></span><textarea v-if="f.type==='textarea'" v-model="values[f.key] as string" rows="4" :required="f.required" :aria-label="f.label" maxlength="8000" /><select v-else-if="f.type==='select'" v-model="values[f.key]" :required="f.required" :aria-label="f.label"><option v-if="f.required" value="" disabled>Tanlang</option><option v-for="o in f.options" :key="o.value" :value="o.value">{{ o.label }}</option></select><div v-else-if="f.type==='multi'" class="editor-multi"><input v-if="(f.options?.length??0)>15" v-model="find" type="search" :aria-label="f.label+' ichidan qidirish'" placeholder="Nom yoki raqam bo‘yicha qidirish" /><small>{{ (values[f.key] as string[]).length }} ta tanlangan</small><div class="editor-options"><label v-for="o in options(f)" :key="o.value"><input type="checkbox" v-model="values[f.key]" :value="o.value" :aria-label="o.label" /><span>{{ o.label }}</span></label></div></div><input v-else-if="f.type==='checkbox'" type="checkbox" v-model="values[f.key]" :required="f.required" :aria-label="f.label" /><input v-else v-model="values[f.key] as string" :type="f.type" :required="f.required" :readonly="!!editId&&f.key==='id'" :aria-label="f.label" :maxlength="f.key==='pinfl'?14:500" :min="f.type==='number'?0:undefined" :max="f.key==='coverage'?100:['age','minAge','maxAge'].includes(f.key)?120:undefined" :step="f.key==='amount'||f.key==='coverage'?'0.01':'1'" :inputmode="f.key==='pinfl'?'numeric':undefined" /><small v-if="f.hint">{{ f.hint }}</small></div></div></fieldset><div v-if="entity==='rule'" class="editor-info"><p>Faol qoida tekshiruvda qo‘llanadi.</p></div><p v-if="error" class="editor-error" role="alert">{{ error }}</p></div><footer><span>* Majburiy maydonlar</span><button type="button" @click="emit('close')">Bekor qilish</button><button class="primary" type="submit" :disabled="saving"><Save :size="16" /> Saqlash</button></footer></form></section></div>
</template>
<style scoped>
.editor-overlay{position:fixed;inset:0;background:#172b235c;z-index:130;display:flex;justify-content:end}.editor{width:min(850px,100%);height:100%;background:#fff;box-shadow:-10px 0 50px #0002;display:flex;flex-direction:column;color:#334155}.editor header{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:22px 28px;border-bottom:1px solid #e2e8f0}.editor header span{font-size:9px;letter-spacing:1.5px;color:#6d8b7c}.editor h2{font-size:20px;font-weight:650;margin-top:6px}.editor form{min-height:0;display:flex;flex-direction:column;flex:1}.editor-body{padding:22px 28px;overflow-y:auto;flex:1}.editor-info{display:flex;align-items:start;gap:10px;background:#f2f7f4;border:1px solid #dce8e0;border-radius:7px;padding:13px;margin-bottom:24px}.editor-info svg{flex-shrink:0;color:#527d65}.editor-info p{font-size:11px;line-height:1.8;color:#64776b;margin:0}.editor fieldset{border:0;padding:0;margin:0 0 28px}.editor legend{font-size:14px;font-weight:650;padding:0 0 14px;width:100%;border-bottom:1px solid #edf1ef;margin-bottom:18px}.editor-grid{display:grid;grid-template-columns:1fr 1fr;gap:19px 20px}.editor-grid>.editor-field{display:flex;flex-direction:column;gap:8px;min-width:0;font-size:12px}.editor-grid .wide{grid-column:1/-1}.editor-grid b{color:#be674d}.editor input:not([type=checkbox]),.editor select,.editor textarea{width:100%;min-width:0;border:1px solid #d7e1db;background:white;border-radius:6px;padding:10px 12px;font-size:12px;line-height:1.5;color:#334155}.editor input[readonly]{background:#f5f7f6;color:#94a3b8}.editor small{font-size:10px;color:#829087;line-height:1.7}.editor input[type=checkbox]{width:15px;height:15px;accent-color:#21794f;flex-shrink:0}.editor-multi{border:1px solid #d7e1db;border-radius:7px;padding:12px}.editor-multi>small{display:block;margin:7px 0}.editor-options{max-height:210px;overflow-y:auto;display:flex;flex-direction:column;gap:10px}.editor-options label{display:flex;align-items:start;gap:9px;font-size:11px;line-height:1.7}.editor-options input{margin-top:3px}.editor footer{border-top:1px solid #e2e8f0;padding:16px 28px;display:flex;align-items:center;gap:12px;background:#fcfdfc}.editor footer>span{margin-right:auto;font-size:10px;color:#94a3b8}.editor button{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid #d7e1db;border-radius:6px;padding:9px 13px;font-size:12px;cursor:pointer}.editor .primary{background:#22784f;border-color:#22784f;color:white}.editor-error{color:#b45342;background:#fff3ef;padding:12px;border-radius:6px;font-size:12px}.editor :focus-visible{outline:2px solid #398264;outline-offset:2px}@media(max-width:600px){.editor-grid{grid-template-columns:1fr}.editor header,.editor-body{padding:18px}.editor h2{font-size:17px}.editor footer{padding:14px}.editor footer>span{display:none}}
</style>
